export function drawCards(state,kind){const deck=(kind==='good'?goodCards:badCards).filter(c=>!Object.keys(c.effects).some(k=>k.startsWith('ferry')&&state.round+1<unlockRounds.ferry||k.startsWith('flight')&&state.round+1<unlockRounds.flight||k.startsWith('rail')&&state.round+1<unlockRounds.rail||k==='portCost'&&state.round+1<10||k==='airportCost'&&state.round+1<13)),unused=deck.filter(c=>!state.cardHistory.some(h=>h.id===c.id)),pool=unused.length>=3?[...unused]:[...deck];const picks=[];while(picks.length<3){state.rng=(Math.imul(state.rng,1664525)+1013904223)>>>0;picks.push(pool.splice(state.rng%pool.length,1)[0].id);}return picks;}
export function chooseCard(state,id){const phase=state.cardPhase;if(!['good','bad'].includes(phase)||!state.cardOffers.includes(id))return false;const c=[...goodCards,...badCards].find(c=>c.id===id);for(const [key,value]of Object.entries(c.effects)){if(key==='credits')state.credits=Math.max(0,state.credits+value);else state.mods[key]=(state.mods[key]??0)+value;}state.cardHistory.push({id,name:c.name,kind:phase,description:c.description});state.cardPhase=phase==='good'?'bad':'done';state.cardOffers=phase==='good'?drawCards(state,'bad'):[];return true;}
